  effect.className="rimuru-water-jet-effect";effect.style.left=`${source.x}%`;effect.style.top=`${source.y}%`;effect.style.setProperty("--jet-distance",`${distance}px`);effect.style.setProperty("--jet-angle",`${angle}deg`);effect.style.setProperty("--jet-duration",`${duration}ms`);effect.innerHTML='<span class="water-jet-charge" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span class="water-jet-beam" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><span class="water-jet-impact" aria-hidden="true"><b></b><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span>';
