  if(["projectile","water_blade"].includes(action.visual.style)){effect.animate([{...start,transform:`translate(-50%,-50%) scale(.4) rotate(${action.visual.style==="water_blade"?"-38deg":"0"})`,opacity:0},{...start,transform:`translate(-50%,-50%) scale(1) rotate(${action.visual.style==="water_blade"?"-22deg":"0"})`,opacity:1,offset:.15},{...end,transform:`translate(-50%,-50%) scale(.9) rotate(${action.visual.style==="water_blade"?"18deg":"0"})`,opacity:1,offset:.82},{...end,transform:`translate(-50%,-50%) scale(1.65) rotate(${action.visual.style==="water_blade"?"42deg":"0"})`,opacity:0}],{duration,easing:"cubic-bezier(.2,.75,.25,1)"});}else if(action.visual.style==="slime_burst"){effect.animate([{...end,transform:"translate(-50%,-50%) scale(.2,.05)",opacity:0},{...end,transform:"translate(-50%,-50%) scale(1.45,.75)",opacity:1,offset:.35},{...end,transform:"translate(-50%,-50%) scale(.75,1.5)",opacity:.9,offset:.68},{...end,transform:"translate(-50%,-50%) scale(2)",opacity:0}],{duration,easing:"ease-out"});}else{effect.animate([{...end,transform:"translate(-50%,-50%) scale(.15) rotate(-25deg)",opacity:0},{...end,transform:"translate(-50%,-50%) scale(1.15) rotate(10deg)",opacity:1,offset:.45},{...end,transform:"translate(-50%,-50%) scale(1.45) rotate(25deg)",opacity:0}],{duration,easing:"ease-out"});}
