function evaluateTabletopExpression(input){
  const original=String(input||"").trim();if(!original)throw new Error("Digite uma conta.");if(original.length>120)throw new Error("A expressão é longa demais.");
  let source=original.replace(/[×x]/gi,"*").replace(/÷/g,"/").replace(/−/g,"-").replace(/\s+/g,"");
  if(!/^[0-9d+\-*/().]+$/i.test(source)||/\d*\.\d*d|d\d*\./i.test(source))throw new Error("Use apenas números, operações, parênteses e dados como 2d6.");
  const rolls=[];source=source.replace(/(^|[^0-9.])([0-9]*)d([0-9]+)(?=$|[^0-9.])/gi,(match,prefix,countText,sidesText)=>{const count=countText?Number(countText):1,sides=Number(sidesText);if(!Number.isInteger(count)||count<1||count>100)throw new Error("Use entre 1 e 100 dados por rolagem.");if(!Number.isInteger(sides)||sides<1||sides>100000)throw new Error("O dado deve ter entre 1 e 100000 lados.");const values=Array.from({length:count},()=>Math.floor(Math.random()*sides)+1),sum=values.reduce((total,value)=>total+value,0);rolls.push(`${count}d${sides} [${values.join(", ")}] = ${sum}`);return `${prefix}${sum}`;});
  const tokens=source.match(/\d+(?:\.\d+)?|[()+\-*/]/g)||[];if(!tokens.length||tokens.join("")!==source)throw new Error("Expressão inválida.");let position=0;
  const factor=()=>{const token=tokens[position];if(token==="+"||token==="-"){position++;const value=factor();return token==="-"?-value:value;}if(token==="("){position++;const value=expression();if(tokens[position]!==")")throw new Error("Feche todos os parênteses.");position++;return value;}if(token&&/^\d/.test(token)){position++;return Number(token);}throw new Error("Expressão incompleta.");};
  const term=()=>{let value=factor();while(tokens[position]==="*"||tokens[position]==="/"){const operator=tokens[position++],right=factor();if(operator==="/"&&right===0)throw new Error("Não é possível dividir por zero.");value=operator==="*"?value*right:value/right;}return value;};
  const expression=()=>{let value=term();while(tokens[position]==="+"||tokens[position]==="-"){const operator=tokens[position++],right=term();value=operator==="+"?value+right:value-right;}return value;};
  const value=expression();if(position!==tokens.length||!Number.isFinite(value))throw new Error("Expressão inválida.");return {value,rolls,expression:original};
}
