  if(inputs.length!==tokens.length||inputs.some((input)=>!tokens.some((token)=>token.id===input.dataset.tokenId))){byId("combatInitiativeFeedback").textContent="Os tokens da mesa mudaram. Feche esta janela e abra novamente.";return;}
